// Nominatim boundingbox = [south, north, west, east] -> viewbox = west,north,east,south
const s = $('Set lead finder settings').first().json;
const b = $json.boundingbox;
if (!b) return [{ json: { found: false, message: `Couldn't find "${s.city}" on OpenStreetMap. Try adding the country, e.g. "Bath, UK".` } }];
return [{ json: { found: true, category: String(s.category).trim(), city: s.city, max_results: Number(s.max_results) || 20,
  viewbox: `${b[2]},${b[1]},${b[3]},${b[0]}`, town: $json.display_name } }];

// Flatten the OpenStreetMap results, keep named businesses, dedupe (OSM id, then name + postcode) and read contact tags
const s = $('Set lead finder settings').first().json;
const KEEP = ['amenity', 'shop', 'craft', 'office', 'healthcare', 'leisure', 'tourism', 'club', 'building', 'emergency'];
const seen = new Set(), seenName = new Set(), perSearch = {}, out = [];
let searched = '';
$input.all().forEach((item, i) => {
  const { places, ctx } = { places: [item.json], ctx: { category: s.category, city: s.city, max_results: s.max_results } };
  const search = `${ctx.category} in ${ctx.city}`;
  const townKey = String(ctx.city || '').split(',')[0].trim().toLowerCase();  // a town's box can reach into the next town
  searched = searched || search;
  const cap = Number(ctx.max_results) || 40;
  for (const p of places || []) {
    if (!p || !p.osm_id || !p.name) continue;
    const t = p.extratags || {};
    const site = t.website || t['contact:website'] || t.url || '';
    if (!KEEP.includes(p.category) && !site && !t.phone && !t['contact:phone']) continue;  // bus stops, roads, areas
    if (s.only_inside_town !== false && townKey.length > 2 && !String(p.display_name || '').toLowerCase().includes(townKey)) continue;
    const id = `osm-${p.osm_type}-${p.osm_id}`;
    const a = p.address || {};
    const postcode = a.postcode || '';
    const nameKey = String(p.name).toLowerCase().replace(/[^a-z0-9]/g, '') + '|' + postcode.replace(/\s/g, '').toLowerCase();
    if (seen.has(id) || seenName.has(nameKey)) continue;
    perSearch[search] = perSearch[search] || 0;
    if (perSearch[search] >= cap) continue;
    seen.add(id); seenName.add(nameKey); perSearch[search]++;
    const town = a.city || a.town || a.village || a.suburb || ctx.city;
    const street = [a.house_number, a.road].filter(Boolean).join(' ');
    let website = String(site).trim();
    if (website && !/^https?:\/\//i.test(website)) website = 'http://' + website;
    out.push({ json: {
      lead_id: id, search, category: String(p.type || ctx.category).replace(/_/g, ' '), name: p.name,
      address: [street, a.suburb, town, postcode].filter(Boolean).join(', ') || p.display_name, postcode, city: town,
      phone: t.phone || t['contact:phone'] || t['contact:mobile'] || '', email: t.email || t['contact:email'] || '',
      website, facebook: t['contact:facebook'] || t.facebook || '', instagram: t['contact:instagram'] || t.instagram || '',
      linkedin: t['contact:linkedin'] || '', opening_hours: t.opening_hours || '',
      osm_url: `https://www.openstreetmap.org/${p.osm_type}/${p.osm_id}`,
      maps_url: 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(`${p.name} ${postcode || town}`),
      lat: p.lat, lon: p.lon,
    } });
  }
});
if (!out.length) return [{ json: { no_results: true, message: `No businesses found for "${searched || s.category + ' in ' + s.city}" on OpenStreetMap. Try a common word such as dentist, cafe, restaurant, hairdresser, plumber or estate agent, or a larger town.` } }];
return out;

// Read the homepage: emails, phones, social profiles and quick website-quality checks (HTTPS, mobile, booking, freshness)
const year = new Date().getFullYear();
const BAD_MAIL = /\.(png|jpe?g|gif|webp|svg|css|js)$|@(example|sentry|wixpress|sentry-next|domain|email)\.|^u00|@2x/;
return $input.all().map((item, i) => {
  const lead = $('Has a website?').itemMatching(i).json;
  const r = item.json || {};
  const html = String(r.body ?? r.data ?? '');
  const status = Number(r.statusCode) || (r.error ? 0 : (html ? 200 : 0));
  const text = html.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>|<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<[^>]+>/g, ' ').replace(/&nbsp;|&#160;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
  const emails = [...new Set([...(html.match(/mailto:([^"'?>\s]+)/gi) || []).map(m => m.slice(7)),
    ...(text.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || [])].map(e => decodeURIComponent(e).toLowerCase().trim()))].filter(e => !BAD_MAIL.test(e));
  const phones = [...new Set((html.match(/tel:([+0-9()\s.-]{7,})/gi) || []).map(t => t.slice(4).trim()))];
  const pick = rx => { const m = html.match(rx); return m ? m[0].replace(/["'<>].*$/, '') : ''; };
  const facebook = lead.facebook || pick(/https?:\/\/(www\.)?facebook\.com\/(?!sharer|share|plugins|tr\b|dialog)[A-Za-z0-9_.\-\/]+/i);
  const instagram = lead.instagram || pick(/https?:\/\/(www\.)?instagram\.com\/(?!p\/|explore)[A-Za-z0-9_.\-]+/i);
  const linkedin = lead.linkedin || pick(/https?:\/\/([a-z]{2,3}\.)?linkedin\.com\/(company|in)\/[A-Za-z0-9_\-%]+/i);
  const others = ['tiktok\\.com\\/@[A-Za-z0-9_.]+', '(twitter|x)\\.com\\/(?!share|intent|home)[A-Za-z0-9_]+', 'youtube\\.com\\/(@|channel\\/|c\\/)[A-Za-z0-9_\\-]+']
    .map(p => pick(new RegExp('https?:\\/\\/(www\\.)?' + p, 'i'))).filter(Boolean);
  const title = ((html.match(/<title[^>]*>([^<]*)/i) || [])[1] || '').trim().slice(0, 120);
  const desc = ((html.match(/<meta[^>]+name=["']description["'][^>]*content=["']([^"']*)/i) || [])[1] || '').slice(0, 200);
  const mobile = /<meta[^>]+name=["']viewport["']/i.test(html);
  const https = /^https:/i.test(lead.website);
  const cy = [...text.matchAll(/(?:©|&copy;|copyright)\s*(?:\d{4}\s*[-–]\s*)?(\d{4})/gi)].map(m => Number(m[1])).filter(y => y > 1995 && y <= year);
  const copyright = cy.length ? Math.max(...cy) : null;
  const booking = /(book (now|online|a table|an appointment)|booking|calendly\.com|fresha\.com|treatwell|setmore|simplybook|opentable|resdiary|acuityscheduling|squareup\.com\/appointments)/i.test(html);
  const gen = ((html.match(/<meta[^>]+name=["']generator["'][^>]*content=["']([^"']*)/i) || [])[1] || '');
  const cms = /wix\.com|wixstatic/i.test(html) ? 'Wix' : /squarespace/i.test(html) ? 'Squarespace' : /wp-content|wordpress/i.test(html + gen) ? 'WordPress'
    : /cdn\.shopify|shopify/i.test(html) ? 'Shopify' : /godaddy|websitebuilder/i.test(html) ? 'GoDaddy builder' : gen.split(' ')[0] || '';
  const contactHref = ((html.match(/href=["']([^"'#]*contact[^"'#]*)["']/i) || [])[1] || '');
  let contact_url = '';
  try { if (contactHref) contact_url = new URL(contactHref, lead.website).href; } catch (e) {}
  const words = text.split(' ').length;
  const issues = [];
  const blocked = [401, 403, 429, 503].includes(status);  // bot protection: the site may be fine in a browser
  if (blocked) {}
  else if (!status || status >= 400) issues.push(status === 404 ? 'website link is broken (404)' : `site not loading (${status || 'no response'})`);
  else {
    if (!https) issues.push('no HTTPS');
    if (!mobile) issues.push('not mobile-friendly (no viewport tag)');
    if (copyright && copyright < year - 2) issues.push(`copyright ${copyright}`);
    if (!desc) issues.push('no meta description');
    if (words < 150) issues.push('very little text');
    if (!booking && /restaurant|cafe|dentist|hairdresser|beauty|salon|clinic|physio|barber|spa|massage|gym|vet/i.test(lead.category)) issues.push('no online booking');
  }
  const site_score = blocked ? '' : Math.max(0, 100 - issues.length * 18 - (!status || status >= 400 ? 40 : 0));
  return { json: { ...lead, email: lead.email || emails[0] || '', other_emails: emails.slice(1, 3).join(', '),
    phone: lead.phone || phones[0] || '', facebook, instagram, linkedin, other_socials: others.join(' '),
    site_status: blocked ? `${status} (blocks automated checks)` : status, site_title: title, site_description: desc, site_cms: cms, site_copyright: copyright || '',
    site_has_booking: booking ? 'yes' : 'no', site_issues: issues.join('; '), site_score, contact_url,
    site_text: text.slice(0, 1500) } };
});

