=You qualify local businesses as sales leads for me.

What I sell: {{ $('Set lead finder settings').first().json.your_service }}
My ideal customer: {{ $('Set lead finder settings').first().json.ideal_customer }}

Business: {{ $json.name }} ({{ $json.category }})
Address: {{ $json.address }}
Website: {{ $json.website || 'none listed on OpenStreetMap' }}
Phone: {{ $json.phone || 'not found' }} | E-mail: {{ $json.email || 'not found' }}
Social profiles: {{ [$json.facebook, $json.instagram, $json.linkedin, $json.other_socials].filter(Boolean).join(' ') || 'none found' }}
Opening hours listed: {{ $json.opening_hours || 'unknown' }}
Website check: {{ $json.website ? ('status ' + $json.site_status + ', built with ' + ($json.site_cms || 'unknown') + ', online booking: ' + $json.site_has_booking) : 'no website' }}
Website issues: {{ $json.site_issues || ($json.website ? (String($json.site_status).includes('blocks') ? 'not checked: the site blocks automated requests, so say nothing about its quality' : 'none detected') : 'no website at all') }}
Homepage title: {{ $json.site_title || '-' }}
Homepage text sample: {{ ($json.site_text || '').slice(0, 900) }}

Rules:
- fit_score 0-100: how likely this business needs AND can pay for what I sell. A missing website or website problems only raise the score when what I sell fixes them.
- reasons: 2-3 short, factual reasons based only on the facts above. Never say the website is broken or down unless the website issues say so.
- opener: 1-2 sentences for a cold e-mail that mention one specific, true detail from the facts above and link it to what I sell. Under 45 words, no flattery cliches ("I came across your amazing business"), no exclamation marks, no invented names, reviews or numbers.
- subject_line: under 7 words, plain, no clickbait.
- Write in {{ $('Set lead finder settings').first().json.language }}.

parameters.jsCode:
// Merge the AI verdict with the business data -> one row per lead for the Leads tab
const s = $('Set lead finder settings').first().json;
const hot = Number(s.min_score_hot) || 70;
const leads = $('Combine leads').all();
return $input.all().map((item, i) => {
  const l = (leads[i] || {}).json || {};
  const o = item.json.output || {};
  const score = Math.max(0, Math.min(100, Math.round(Number(o.fit_score) || 0)));
  return { json: {
    lead_id: l.lead_id, found_at: $now.toFormat('yyyy-MM-dd HH:mm'), search: l.search, name: l.name, category: l.category,
    address: l.address, postcode: l.postcode, city: l.city, phone: l.phone, email: l.email, other_emails: l.other_emails || '',
    website: l.website, facebook: l.facebook, instagram: l.instagram, linkedin: l.linkedin, other_socials: l.other_socials || '',
    opening_hours: l.opening_hours, has_website: l.website ? 'yes' : 'no', site_status: l.site_status || '',
    site_issues: l.site_issues || (l.website ? '' : 'no website'), site_score: l.website ? l.site_score : 0,
    fit_score: score, priority: score >= hot ? 'high' : score >= 45 ? 'medium' : 'low',
    reasons: (o.reasons || []).join('; '), pitch_angle: o.pitch_angle || '', opener: o.opener || '', subject_line: o.subject_line || '',
    osm_url: l.osm_url, maps_url: l.maps_url, status: 'new',
  } };
});

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// One summary item for the results page
const rows = $('Build lead rows').all().map(i => i.json).sort((a, b) => b.fit_score - a.fit_score);
const high = rows.filter(r => r.priority === 'high').length;
const noSite = rows.filter(r => r.has_website === 'no').length;
const withEmail = rows.filter(r => r.email).length;
const top = rows.slice(0, 8).map(r => `<tr><td><b>${esc(r.name)}</b><br><small>${esc(r.address)}</small></td><td>${r.fit_score}</td><td>${esc(r.site_issues || '-')}</td><td>${esc(r.opener)}</td></tr>`).join('');
return [{ json: { count: rows.length, high, html: `<p><b>${rows.length}</b> leads saved to your Leads sheet: ${high} high priority, ${withEmail} with an e-mail, ${noSite} without a website.</p>
<table border="1" cellpadding="6" style="border-collapse:collapse;font-size:13px"><tr><th>Business</th><th>Fit</th><th>Website issues</th><th>Opener</th></tr>${top}</table>` } }];
